BeforeAll {
    . (Join-Path (Split-Path $PSScriptRoot) 'TestSupport.ps1')
    # A synthetic repository listing generated by a child process: large native output, never a real work repository.
    $script:Generator = Join-Path $TestDrive 'generate-tree.ps1'
    [IO.File]::WriteAllText($script:Generator, @'
param([int]$Files, [int]$Code = 0)
[Console]::OutputEncoding = [Text.UTF8Encoding]::new($false)
$writer = [Console]::Out
for ($index = 0; $index -lt $Files; $index++) {
    $writer.WriteLine("src/module$($index % 97)/area$($index % 13)/Generated$index.cs  modified  $($index * 7 % 1000) lines")
}
if ($Code) { [Console]::Error.WriteLine("fatal: synthetic failure after $Files files") }
exit $Code
'@)
    function Get-TreeArgument([int]$Files, [int]$Code = 0) { @('-NoProfile','-NonInteractive','-File',$script:Generator,[string]$Files,[string]$Code) }
}

Describe 'Measured deliveries of generated workloads' {
    BeforeAll {
        # The scenario owns its history, configuration and session.
        $script:Database = Join-Path $TestDrive 'scenario.sqlite'
        $script:Configuration = Join-Path $TestDrive 'scenario.yaml'
        [IO.File]::WriteAllText($script:Configuration, "general:`n  timeoutSeconds: 120`n  measureAlternateFormat: true`n  recallWindowMinutes: 30")
        $script:Previous = @{ OPUMPER2_DB_PATH = (Set-TestEnvironment OPUMPER2_DB_PATH $script:Database)
            OPUMPER2_CONFIG_PATH = (Set-TestEnvironment OPUMPER2_CONFIG_PATH $script:Configuration); OPUMPER2_SESSION = (Set-TestEnvironment OPUMPER2_SESSION 'scenario') }
        InModuleScope FrenchExDev.OPumper2.PoSh { $script:OP2Routes.Clear() }
        Register-OPumper2 -Id fixture.tree -Route @('tree') -ProviderId fixture -Handler {
            param($call)
            $state = @{ Files = 0L; Modules = [Collections.Generic.HashSet[string]]::new() }
            $native = FrenchExDev.OPumper2.PoSh\Pump-Me $script:OP2TestExecutable -ArgumentList (Get-TreeArgument ([int]$call.ArgumentList[0])) -State $state `
                -OnRecord { param($record, $s) if ($record.Stream -eq 'stdout') { $s.Files++; [void]$s.Modules.Add($record.Text.Split('/')[1]) } } `
                -Complete { param($s) [pscustomobject]@{ Files = $s.Files; Modules = @($s.Modules) } } -AsObject
            New-OPumper2Result -Completion $native -Projection { param($data) [ordered]@{ Files = $data.Files; Modules = $data.Modules.Count } }
        } | Out-Null
        $count = { param($record, $s) if ($record.Stream -eq 'stdout') { $s.Lines++ } }
        Pump-Me tree 20000 -AsYaml | Out-Null
        Pump-Me tree 20000 -AsYaml | Out-Null
        Pump-Me tree 500 -AsJson | Out-Null
        Pump-Me $script:OP2TestExecutable -ArgumentList (Get-TreeArgument 5000) -State @{ Lines = 0L } -OnRecord $count -Complete { param($s) $s.Lines } -AsYaml | Out-Null
        Pump-Me $script:OP2TestExecutable -ArgumentList (Get-TreeArgument 3000 2) -OnRecord {} -AsYaml | Out-Null
        $script:Local = Pump-Me tree 1000 -AsObject
        Pump-Me $script:OP2TestExecutable -ArgumentList (Get-TreeArgument 2000) -OnRecord { param($record) $record.Text } -MaxItems 5 -AsJson | Out-Null
    }
    AfterAll {
        foreach ($name in $script:Previous.Keys) { Set-TestEnvironment $name $script:Previous[$name] | Out-Null }
        InModuleScope FrenchExDev.OPumper2.PoSh { $script:OP2Routes.Clear() }
    }
    It 'keeps a local object out of the deliveries with its complete Data and capture' {
        $script:Local.Data.Files | Should -Be 1000
        $script:Local.Capture.Stdout.Length | Should -BeGreaterThan 40000
        $script:Local.Measurement.Status | Should -Be 'SourceMeasured'
    }
    It 'measures what each delivery saved, recalled, lost and was made of' {
        $data = (Get-OPumper2Gain -AsObject).Data
        $data.Deliveries | Should -Be 6
        $data.Compared | Should -Be 6
        $data.TokenRate | Should -BeGreaterThan 0.98
        $data.SourceTokens | Should -BeGreaterThan 400000
        $data.Reruns | Should -Be 1
        $data.Stored | Should -Be 6
        $data.Recalled | Should -Be 0
        $data.Lossy | Should -Be 1
        $data.Local.Invocations | Should -Be 1
        $data.Local.SourceTokens | Should -BeGreaterThan 10000
        $data.Layers.Data | Should -BeGreaterThan 0
        $data.Layers.Records | Should -BeGreaterThan 0
        $data.Layers.Excerpt | Should -BeGreaterThan 0
        $data.Layers.Envelope | Should -BeGreaterThan 0
        ($data.Layers.Envelope + $data.Layers.Data + $data.Layers.Records + $data.Layers.Excerpt) | Should -Be $data.OutputTokens
        $data.Alternate.Compared | Should -Be 6
        $data.Alternate.Delivered | Should -Be $data.OutputTokens
    }
    It 'breaks the deliveries down by command, provider, format, outcome and session' {
        function Get-Breakdown([string[]]$By) { @((Get-OPumper2Gain -GroupBy $By -AsObject).Data.Groups | ForEach-Object { "$($_.Key)=$($_.Compared)" }) -join ',' }
        Get-Breakdown Command | Should -Match '^fixture\.tree=3,'
        Get-Breakdown Provider | Should -BeExactly '(none)=3,fixture=3'
        Get-Breakdown Format | Should -BeExactly 'json=2,yaml=4'
        Get-Breakdown Outcome | Should -BeExactly 'Failed=1,Success=5'
        Get-Breakdown Session | Should -BeExactly 'scenario=6'
        $history = (Get-OPumper2Gain -History 6 -Top 1 -Worst 1 -AsObject).Data
        (@($history.History | ForEach-Object { "$($_.Command):$($_.Format):$($_.Rerun)" }) -join ',') | Should -Match '^fixture\.tree:yaml:False,fixture\.tree:yaml:True,fixture\.tree:json:False,'
        $history.Top[0].Command | Should -Be 'fixture.tree'
        $history.Top[0].SavedTokens | Should -BeGreaterThan $history.Worst[0].SavedTokens
    }
    It 'reports for people, merges histories and clears one of them' {
        $text = Get-OPumper2Gain -GroupBy Provider -History 2 -Graph -AsText
        $text | Should -Match 'fixture\s+3\s+'
        $text | Should -Match 'Delivered tokens: envelope '
        $text | Should -Match 'In json/yaml: '
        $text | Should -Match '(?m)^Saved tokens per day$'
        Get-OPumper2Gain -AsLine | Should -Match '^OPumper2: .+ tokens saved \(9\d\.\d %\), 6 deliveries, 1 reruns, 0 recalls$'
        $copy = Join-Path $TestDrive 'scenario-copy.sqlite'
        Copy-Item -LiteralPath $script:Database -Destination $copy
        $merged = (Get-OPumper2Gain -DatabasePath $script:Database,$copy -AsObject).Data
        $merged.Deliveries | Should -Be 12
        $merged.Reruns | Should -Be 2
        (Clear-OPumper2Measurement -All -DatabasePath $copy -Confirm:$false).Deliveries | Should -Be 6
        (Get-OPumper2Gain -DatabasePath $copy -AsObject).Data.Deliveries | Should -Be 0
        (Get-OPumper2Gain -AsObject).Data.Deliveries | Should -Be 6
    }
}
